    fact_check_status: `Wire Summary — Attributed to Primary Source`,
    tags: `Politics, News, India`,
    summary: `Mumbai The Nationalist Congress Party–Sharadchandra Pawar (NCP-SP) on Friday (November 27, 2026) announced its support for the delimitation Bills. The NCP-SP, led by Sharad Pawar and his daughter Supriya Sule, is a part of the Opposition bl`,
    content: `Mumbai The Nationalist Congress Party–Sharadchandra Pawar (NCP-SP) on Friday (November 27, 2026) announced its support for the delimitation Bills. The NCP-SP, led by Sharad Pawar and his daughter Supriya Sule, is a part of the Opposition bloc, the Indian National Developmental, Inclusive Alliance (INDIA).

Most of the INDIA parties oppose the Centre’s delimitation plan, and the Congress has termed the decision of its ally, the NCP-SP, to support the Bills as "unfortunate". Earlier in the day, Shiv Sena (UBT) leader Sanjay Raut had referred to parties supporting the Bills as "traitors”.

https://www.thehindu.com/topic/shiv-sena-uddhav-balasaheb-thackeray/ Union Cabinet clears delimitation bill Union Cabinet clears delimitation bill A similar attempt by the government was rejected in the Lok Sabha during the Monsoon session in April Union Cabinet clears delimitation bill storyline 1 NCP-SP leader Jitendra Awhad on Friday (November 27, 2026) said in Mumbai, “We will support the delimitation Bill.

We will attend the INDIA Bloc meeting.” He was referring to a meeting of INDIA bloc floor leaders called for Saturday morning to discuss the Opposition’s joint response to the Bills. Meanwhile, Ms. Sule will be in Mumbai over the weekend, as Mr. Pawar continues to remain hospitalised in the city.

She will go to Delhi only on Monday (November 30) to attend the parliamentary session, she announced on her WhatsApp status. Mr. Pawar is likely to be discharged over the weekend, Mr. Awhad said. “Supriya Sule, along with the eight party MPs, has decided to support the delimitation Bill.

The party will do so accordingly. That is the final decision,” Mr. Awhad said minutes after meeting Mr. Pawar at hospital. The party has already issued a whip to all its leaders to remain present in Delhi. Special session of Parliament: Congress, NCP(SP) issue whip to party MPs Special session of Parliament: Congress, NCP(SP) issue whip to party MPs The government has called for a special sitting of Parliament beginning Monday (November 30, 2026), where it is likely to table an amended Delimitation Bill Special session of Parliament: Congress, NCP(SP) issue whip to party MPs storyline 1 When asked about his discussion with Mr.

Pawar, he said that they did not discuss the party’s official stance per se. “The general point being discussed was that delimitation is a constitutional process. It will have to be done at some point,” he said. The Union Cabinet on Friday approved the Constitution Amendment Bill, providing a proportionate increase of 50% seats across all States.

This ratio will continue for 25 years till it changes in accordance with the population in the Census after 2051. The Women’s Reservation law will come into effect along with the increase in seats. ‘Deeply unfortunate’ Reacting to NCP SP’s announcement, Congress leader Sachin Sawant called the decision “deeply unfortunate”.

“It helps the [Narendra] Modi government’s authoritarian mindset. This Bill has been introduced to tighten the noose of authoritarianism that has been tightening for the past 12 years. The government’s intentions behind this Bill are not honest,” he said in a post on X. However, Maharashtra Congress sources told The Hindu that the party had anticipated that the NCP-SP would take this stance.

Why Delimitation Bill failed to pass in Parliament in April 2026 Why Delimitation Bill failed to pass in Parliament in April 2026 Why the Delimitation Bill failed in Parliament in April 2026 and how the political arithmetic changed since then; here’s what to know Why Delimitation Bill failed to pass in Parliament in April 2026 storyline 1 The INDIA bloc has been rallying against the delimitation Bills.

Criticising the Union government, Shiv Sena (UBT) MP Sanjay Raut called the move a ploy. “Realising they are set to lose in 2029, they have devised a new ploy. They intend to bring in 860 MPs and carry out a delimitation exercise. This Bill is anti-national and anti-democratic; it must be opposed.

Those who vote in favour of this Bill will be traitors to the nation. Their names will be recorded in history as traitors,” he said. He added that the parties of the INDIA bloc cannot take an independent decision. “Whatever decision is to be taken will be taken within the INDIA bloc,” he said

---

**Original Source:** [The Hindu](https://www.thehindu.com/news/national/ncpsp-decides-to-back-delimitation-says-jitendra-awhad/article71751118.ece)`,
