    source_name: `India TV Hindi`,
    source_url: `https://www.indiatv.in/india/politics/jagan-mohan-reddy-ysrcp-says-it-will-support-delimitation-bill-in-parliament-if-it-ensures-regional-balance-2026-11-27-1256709`,
    source_courtesy: `Source: India TV Hindi`,
